diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..face292 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,65 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS_11050 = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006: descuento global del 10 % sobre el total, con IVA y neto recalculados", () => {
+  assert.deepEqual(calcularFactura(LINEAS_11050, { descuentoGlobal: 10 }), {
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+});
+
+test("RF-006: el monto descontado se redondea al centavo con Math.round", () => {
+  // 1050 * 15 / 100 = 157,5 -> 158; total 892
+  const f = calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1050 }], { descuentoGlobal: 15 });
+  assert.equal(f.totalCentavos, 892);
+});
+
+test("RF-006: descuento 0 igual a sin descuento; descuento 100 deja todo en 0", () => {
+  assert.deepEqual(calcularFactura(LINEAS_11050, { descuentoGlobal: 0 }), calcularFactura(LINEAS_11050));
+  assert.deepEqual(calcularFactura(LINEAS_11050, { descuentoGlobal: 100 }), {
+    totalCentavos: 0,
+    ivaCentavos: 0,
+    netoCentavos: 0,
+  });
+});
+
+test("RF-006: descuentoGlobal inválido lanza RangeError", () => {
+  for (const valor of [-1, 101, 12.5, NaN, "10", null]) {
+    assert.throws(() => calcularFactura(LINEAS_11050, { descuentoGlobal: valor }), RangeError, `valor: ${String(valor)}`);
+  }
+});
+
+test("RF-006: sin segundo parámetro o sin descuentoGlobal el resultado no cambia", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS_11050), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_11050, {}), esperado);
+});
+
+test("RF-006: el resultado tiene exactamente las claves de siempre", () => {
+  assert.deepEqual(Object.keys(calcularFactura(LINEAS_11050, { descuentoGlobal: 10 })).sort(), [
+    "ivaCentavos",
+    "netoCentavos",
+    "totalCentavos",
+  ]);
+});
+
+test("RF-006: emitirFactura no cambia, sigue congelada y sin campos nuevos", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS_11050 });
+  assert.ok(Object.isFrozen(f));
+  assert.deepEqual(Object.keys(f).sort(), ["estado", "items", "ivaCentavos", "netoCentavos", "nit", "numero", "razonSocial", "totalCentavos"]);
+  assert.equal(f.totalCentavos, 11050);
+  // emitirFactura no recibe el descuento: si se le pasa, se ignora.
+  const g = emitirFactura({ numero: 9, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS_11050, descuentoGlobal: 10 });
+  assert.equal(g.totalCentavos, 11050);
+  assert.ok(!("descuentoGlobal" in g));
+});
